WITH RankedPosts AS (SELECT p.Id AS PostId, p.OwnerUserId, p.CreationDate, p.Title, p.Score, ROW_NUMBER() OVER (PARTITION BY p.OwnerUserId ORDER BY p.Score DESC NULLS FIRST) AS Rank FROM Posts AS p WHERE p.CreationDate >= CAST('2024-10-01 12:34:56' AS Nullable(DateTime)) - INTERVAL '1' YEAR), UserReputation AS (SELECT u.Id AS UserId, u.Reputation, COUNT(DISTINCT b.Id) AS BadgeCount FROM Users AS u LEFT JOIN Badges AS b ON u.Id = b.UserId WHERE u.Reputation > 1000 GROUP BY u.Id, u.Reputation), PostComments AS (SELECT c.PostId, COUNT(c.Id) AS CommentCount, GROUP_CONCAT(c.Text, '; ') AS AllComments FROM Comments AS c GROUP BY c.PostId) SELECT rp.PostId, rp.Title, rp.Score, ur.Reputation, ur.BadgeCount, pc.CommentCount, COALESCE(pc.AllComments, 'No comments') AS AllComments FROM RankedPosts AS rp JOIN UserReputation AS ur ON rp.OwnerUserId = ur.UserId LEFT JOIN PostComments AS pc ON rp.PostId = pc.PostId WHERE rp.Rank <= 5 ORDER BY rp.Score DESC NULLS FIRST, ur.Reputation DESC NULLS FIRST LIMIT 100